mapper.select:
select id, avatar_id, voice, scenario_id, status, started_at, ended_at
from training_session where user_id = #{userId}

    and (started_at < #{beforeTime}
        or (started_at = #{beforeTime} and id < #{beforeId}))

order by started_at desc, id desc limit #{limit}

select t.id, t.session_id, t.seq, t.user_text, t.assistant_text, t.audio_path, t.latency_ms, t.created_at, t.updated_at
from conversation_turn t join training_session s on s.id = t.session_id
where s.user_id = #{userId} and s.id = #{sessionId} and t.id > #{afterId}
order by t.id asc limit #{limit}
